#!/bin/sh
# Usage: verify-site.sh <base-url>   e.g. http://127.0.0.1:8123/personal-blog
B=$1; fails=0
check() { if eval "$2"; then echo "PASS $1"; else echo "FAIL $1"; fails=$((fails+1)); fi; }
code() { curl -s -o /dev/null -w '%{http_code}' "$1"; }
body() { curl -s "$1"; }
check "home lists the pinned post first, marked, then the newest" '[ "$(body $B/ | grep -o "/personal-blog/posts/[A-Za-z0-9-][A-Za-z0-9-]*/" | uniq | head -2 | tr "\n" " ")" = "/personal-blog/posts/01K7R6F2M8KD4S9V1YCX3BNQWE/ /personal-blog/posts/nextjs-static-export/ " ] && body $B/ | grep -q "class=\"pin-badge\">置頂"'
check "published post renders markdown" 'body $B/posts/01K7M4Y7P65BDCF8AHRTQY7ZQF/ | grep -q "<h2 id=\"為什麼自建-cms\">為什麼自建 CMS</h2>"'
check "published post is indexable" '! body $B/posts/01K7M4Y7P65BDCF8AHRTQY7ZQF/ | grep -q noindex'
check "archived post shows archive notice" 'body $B/posts/01K6ZT3H5J7K9M1N3P5Q7R9S1T/ | grep -q "<h1>文章已封存</h1>"'
check "archived post is noindex" 'body $B/posts/01K6ZT3H5J7K9M1N3P5Q7R9S1T/ | grep -q "noindex"'
check "archived post absent from list" '! body $B/posts/ | grep -q 01K6ZT3H5J7K9M1N3P5Q7R9S1T'
check "a post with a slug lives at its slug" 'body $B/posts/nextjs-static-export/ | grep -q "rel=\"canonical\" href=\"https://example.com/personal-blog/posts/nextjs-static-export/\""'
check "its earlier doc_id URL redirects to the slug and is noindex" 'p=$(body $B/posts/01K7P2B9X3QW8N5R7TZ4HJMVCD/); echo "$p" | grep -q "http-equiv=\"refresh\" content=\"0; url=/personal-blog/posts/nextjs-static-export/\"" && echo "$p" | grep -q "rel=\"canonical\" href=\"https://example.com/personal-blog/posts/nextjs-static-export/\"" && echo "$p" | grep -q noindex'
check "sitemap lists the slug URL and leaves out the redirect" 's=$(body $B/sitemap.xml); echo "$s" | grep -q "/posts/nextjs-static-export/" && ! echo "$s" | grep -q 01K7P2B9X3QW8N5R7TZ4HJMVCD'
check "unknown docId is not generated" '[ "$(code $B/posts/01K7ZZZZZZZZZZZZZZZZZZZZZZ/)" = 404 ]'
check "topic page lists only its posts" 'p=$(body $B/topics/backend/); echo "$p" | grep -q 01K7R6F2M8KD4S9V1YCX3BNQWE && ! echo "$p" | grep -q nextjs-static-export'
check "tag page lists tagged posts" 'body $B/tags/python/ | grep -q 01K7M4Y7P65BDCF8AHRTQY7ZQF'
check "assets resolve under basePath" 'a=$(body $B/ | grep -o "/personal-blog/_next/static/[^\"]*\.css" | head -1); [ -n "$a" ] && [ "$(curl -s -o /dev/null -w %{http_code} "${B%/personal-blog}$a")" = 200 ]'
check "snapshot image is served under basePath" 'i=$(body $B/posts/01K7M4Y7P65BDCF8AHRTQY7ZQF/ | grep -o "src=\"/personal-blog/images/[^\"]*" | head -1 | cut -d\" -f2); [ -n "$i" ] && [ "$(curl -s -o /dev/null -w %{http_code} "${B%/personal-blog}$i")" = 200 ]'
check "article list shows the cover as a thumbnail and the author's excerpt" 'p=$(body $B/posts/); t=$(echo "$p" | grep -o "class=\"thumbnail\" src=\"/personal-blog/thumbs/[^\"]*" | head -1 | cut -d\" -f4); [ -n "$t" ] && [ "$(code "${B%/personal-blog}$t")" = 200 ] && echo "$p" | grep -q "class=\"excerpt\">自建 CMS 系列的第一篇"'
check "sitemap lists published posts with absolute URLs" 'body $B/sitemap.xml | grep -q "<loc>https://example.com/personal-blog/posts/01K7M4Y7P65BDCF8AHRTQY7ZQF/</loc>"'
check "sitemap leaves out archived posts" '! body $B/sitemap.xml | grep -q 01K6ZT3H5J7K9M1N3P5Q7R9S1T'
check "post has a canonical URL" 'body $B/posts/01K7M4Y7P65BDCF8AHRTQY7ZQF/ | grep -q "rel=\"canonical\" href=\"https://example.com/personal-blog/posts/01K7M4Y7P65BDCF8AHRTQY7ZQF/\""'
check "about page links to GitHub" 'body $B/about/ | grep -q "href=\"https://github.com/Hack-Ray\""'
check "about page shows the profile headline, Markdown intro and project" 'p=$(body $B/about/); echo "$p" | grep -q "後端工程師，偏好簡單、好維護的系統" && echo "$p" | grep -q "<strong>Python</strong>" && echo "$p" | grep -q "href=\"https://github.com/Hack-Ray/personal-blog\""'
check "search metadata lists published posts and excludes archived ones" 'm=$(body $B/search-metadata.json); echo "$m" | grep -q 01K7M4Y7P65BDCF8AHRTQY7ZQF && ! echo "$m" | grep -q 01K6ZT3H5J7K9M1N3P5Q7R9S1T'
check "header search form submits q to the search page" 'f=$(body $B/ | grep -o "<form role=\"search\"[^>]*>.*</form>"); echo "$f" | grep -q "action=\"/personal-blog/search/\"" && echo "$f" | grep -q "name=\"q\""'
check "header title links home and home has a single h1" 'body $B/ | grep -q "class=\"site-title\" href=\"/personal-blog/\"" && [ "$(body $B/ | grep -o "<h1" | wc -l)" = 1 ]'
check "footer links to GitHub and the RSS feed" 'f=$(body $B/ | grep -o "<footer.*</footer>"); echo "$f" | grep -q "href=\"https://github.com/Hack-Ray\"" && echo "$f" | grep -q "href=\"/personal-blog/feed.xml\""'
check "feed is served as RSS with items" 'x=$(body $B/feed.xml); echo "$x" | grep -q "<rss version=\"2.0\" xmlns:atom=" && [ "$(echo "$x" | grep -o "<item>" | wc -l)" -ge 1 ] && echo "$x" | python3 -c "import sys, xml.etree.ElementTree as E; E.fromstring(sys.stdin.read())"'
check "pages advertise the feed" 'body $B/ | grep -q "rel=\"alternate\" type=\"application/rss+xml\""'
check "code blocks are highlighted for light and dark" 'p=$(body $B/posts/01K7M4Y7P65BDCF8AHRTQY7ZQF/); echo "$p" | grep -q "<pre class=\"shiki" && echo "$p" | grep -q "style=\"--shiki-light:#[0-9A-Fa-f]*;--shiki-dark:#"'
check "article navigation links both ways in the middle and not past the newest" 'p=$(body $B/posts/01K7M4Y7P65BDCF8AHRTQY7ZQF/); echo "$p" | grep -q "rel=\"prev\"" && echo "$p" | grep -q "rel=\"next\"" && ! body $B/posts/nextjs-static-export/ | grep -q "rel=\"next\""'
check "archived post has no article navigation" '! body $B/posts/01K6ZT3H5J7K9M1N3P5Q7R9S1T/ | grep -q "post-nav"'
check "published post has a comments section and archived post has none" 'body $B/posts/01K7M4Y7P65BDCF8AHRTQY7ZQF/ | grep -q "class=\"comments\"" && ! body $B/posts/01K6ZT3H5J7K9M1N3P5Q7R9S1T/ | grep -q "class=\"comments\""'
check "article with an image has an absolute og:image and a large twitter card" 'p=$(body $B/posts/01K7M4Y7P65BDCF8AHRTQY7ZQF/); echo "$p" | grep -q "property=\"og:image\" content=\"https://[^\"]*/personal-blog/images/" && echo "$p" | grep -q "name=\"twitter:card\" content=\"summary_large_image\""'
check "article without an image shares the default image on a summary card" 'p=$(body $B/posts/nextjs-static-export/); echo "$p" | grep -q "property=\"og:image\" content=\"https://example.com/personal-blog/og-default.png\"" && echo "$p" | grep -q "name=\"twitter:card\" content=\"summary\""'
check "article keeps the site-wide Open Graph fields" 'p=$(body $B/posts/01K7M4Y7P65BDCF8AHRTQY7ZQF/); echo "$p" | grep -q "og:site_name\" content=\"Hack-Ray 的技術筆記" && echo "$p" | grep -q "og:locale\" content=\"zh_TW" && echo "$p" | grep -q "og:type\" content=\"article"'
check "the site title from profile.json names the header, page titles and the feed link" 'p=$(body $B/); echo "$p" | grep -q "class=\"site-title\" href=\"/personal-blog/\">Hack-Ray 的技術筆記</a>" && echo "$p" | grep -q "<title>Hack-Ray 的技術筆記</title>" && body $B/posts/ | grep -q "<title>文章 | Hack-Ray 的技術筆記</title>" && echo "$p" | grep -q "type=\"application/rss+xml\" title=\"Hack-Ray 的技術筆記\"" && ! echo "$p" | grep -q "Personal Blog"'
check "home carries the site description" 'body $B/ | grep -q "name=\"description\" content=\"後端、自動化與自建 CMS 的軟體工程文章\""'
check "feed channel uses the site title and description" 'x=$(body $B/feed.xml); echo "$x" | grep -q "<title>Hack-Ray 的技術筆記</title>" && echo "$x" | grep -q "<description>後端、自動化與自建 CMS 的軟體工程文章</description>"'
check "home uses the website Open Graph type" 'body $B/ | grep -q "og:type\" content=\"website"'
check "article meta shows reading time and lists do not" 'body $B/posts/01K7M4Y7P65BDCF8AHRTQY7ZQF/ | grep -q "約 1 分鐘" && ! body $B/posts/ | grep -q "分鐘"'
check "long article has a table of contents whose links resolve to heading ids" 'p=$(body $B/posts/01K7M4Y7P65BDCF8AHRTQY7ZQF/); (n=0; for id in $(echo "$p" | grep -o "<nav class=\"toc\".*</nav>" | grep -o "href=\"#[^\"]*" | cut -c8-); do n=$((n+1)); echo "$p" | grep -q "<h[23] id=\"$id\"" || exit 1; done; [ $n -ge 3 ])'
check "short article has no table of contents" '! body $B/posts/nextjs-static-export/ | grep -q "class=\"toc\""'
check "pages ship the theme init script in head and a theme toggle in the header" 'p=$(body $B/); echo "$p" | grep -q "<head>.*localStorage.getItem(.theme.*</head>" && echo "$p" | grep -q "class=\"theme-toggle\""'
check "topic and tag index pages list each with a count and the header links to them" 'body $B/topics/ | grep -q "href=\"/personal-blog/topics/backend/\">Backend<span class=\"meta\">2</span>" && body $B/tags/ | grep -q "href=\"/personal-blog/tags/python/\">#Python<span class=\"meta\">" && body $B/ | grep -q "<nav>.*href=\"/personal-blog/topics/\""'
check "article shows related articles" 'body $B/posts/01K7M4Y7P65BDCF8AHRTQY7ZQF/ | grep -q "<section class=\"related\""'
check "code blocks carry a hidden copy button" 'p=$(body $B/posts/01K7M4Y7P65BDCF8AHRTQY7ZQF/); echo "$p" | grep -q "<div class=\"code-block\"><pre class=\"shiki" && echo "$p" | grep -q "</pre><button type=\"button\" class=\"copy-code\" aria-live=\"polite\" hidden>"'
check "footer defaults to the profile name" 'body $B/ | grep -o "<footer.*</footer>" | grep -q "© [0-9]* Hack-Ray"'
check "updated article shows its update date and series" 'p=$(body $B/posts/01K7R6F2M8KD4S9V1YCX3BNQWE/); echo "$p" | grep -q "更新於 <time dateTime=\"2026-10-12" && echo "$p" | grep -q "<nav class=\"series\"" && echo "$p" | grep -q "<span aria-current=\"page\">沒有標籤的短文</span>"'
check "archive page lists posts by year and month" 'p=$(body $B/archive/); echo "$p" | grep -q "<h2>2026 年</h2>" && echo "$p" | grep -q "<h3>9 月</h3>" && echo "$p" | grep -q 01K7R6F2M8KD4S9V1YCX3BNQWE'
check "posts page links the archive and needs no second page yet" 'body $B/posts/ | grep -q "href=\"/personal-blog/archive/\"" && ! body $B/posts/ | grep -q "class=\"pagination\""'
check "external links open in a new tab with a marker" 'body $B/posts/01K7M4Y7P65BDCF8AHRTQY7ZQF/ | grep -q "href=\"https://fastapi.tiangolo.com/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"external\""'
check "404 page offers search" 'body $B/404.html | grep -q "class=\"not-found-search\""'
check "pages do not embed the 404 latest-post list" '! body $B/topics/frontend/ | grep -q 01K7M4Y7P65BDCF8AHRTQY7ZQF'
check "404 latest-post list is a small file of published titles" 'p=$(body $B/latest-posts.json); echo "$p" | grep -q "\"docId\":\"01K7R6F2M8KD4S9V1YCX3BNQWE\"" && ! echo "$p" | grep -q 01K6ZT3H5J7K9M1N3P5Q7R9S1T && ! echo "$p" | grep -q markdown'
check "list pages share the default image" 'body $B/posts/ | grep -q "property=\"og:image\" content=\"https://example.com/personal-blog/og-default.png\"" && [ "$(code $B/og-default.png)" = 200 ]'
check "pages link the favicon, SVG icon and touch icon, and each is served" 'p=$(body $B/posts/); (for f in favicon.ico icon.svg apple-touch-icon.png; do echo "$p" | grep -q "href=\"/personal-blog/$f\"" && [ "$(code $B/$f)" = 200 ] || exit 1; done; echo "$p" | grep -q "rel=\"apple-touch-icon\" href=\"/personal-blog/apple-touch-icon.png\" sizes=\"180x180\"")'
check "feed links to itself" 'body $B/feed.xml | grep -q "<atom:link href=\"https://example.com/personal-blog/feed.xml\" rel=\"self\""'
check "404.html exists for GitHub Pages" '[ "$(code $B/404.html)" = 200 ]'
echo "failures=$fails"; [ $fails = 0 ]
